            value.evolution.relative_tolerances[0] = 2e-5;
            value
        },
    ] {
        assert!(compare::validate_manifest_pair(&left, &changed).is_err());
    }

    let mut changed = right.clone();
    changed.comparison_kind = ComparisonKind::MatchedSpatial;
    assert!(compare::validate_manifest_pair(&left, &changed).is_err());
}

